120      int diff = 0;
   121      int size;
   122      int is_epoch = FLB_FALSE;
   123      char *tmp;
   124      struct mk_list *head;
   125      struct flb_parser *p;
   126      struct flb_regex *regex;
   127
   128      /* Iterate current parsers and make sure the new one don't exists */
   129      mk_list_foreach(head, &config->parsers) {
   130          p = mk_list_entry(head, struct flb_parser, _head);
   131          if (strcmp(p->name, name) == 0) {
   132              flb_error("[parser] parser named '%s' already exists, skip.",
   133                        name);
   134              return NULL;
   135          }
   136      }
   137
   138      /* Allocate context */
   139      p = flb_calloc(1, sizeof(struct flb_parser));
   140      if (!p) {
   141          flb_errno();
   142          return NULL;
   143      }
   144      p->decoders = decoders;
   145
   146      /* Format lookup */
   147      if (strcasecmp(format, "regex") == 0) {
   148          p->type = FLB_PARSER_REGEX;
   149      }
   150      else if (strcasecmp(format, "json") == 0) {
   151          p->type = FLB_PARSER_JSON;
   152      }
   153      else if (strcmp(format, "ltsv") == 0) {
   154          p->type = FLB_PARSER_LTSV;
   155      }
   156      else if (strcmp(format, "logfmt") == 0) {
   157          p->type = FLB_PARSER_LOGFMT;
   158      }
   159      else {
   160          flb_error("[parser:%s] Invalid format %s", name, format);
   161          flb_free(p);
   162          return NULL;
   163      }
   164
   165      if (p->type == FLB_PARSER_REGEX) {
   166          if (!p_regex) {
   167              flb_error("[parser:%s] Invalid regex pattern", name);
   168              flb_free(p);
   169              return NULL;
   170          }
   171
   172          regex = flb_regex_create(p_regex);
   173          if (!regex) {
   174              flb_error("[parser:%s] Invalid regex pattern %s", name, p_regex);
   175              flb_free(p);
   176              return NULL;
   177          }
   178          p->regex = regex;
   179          p->p_regex = flb_strdup(p_regex);
   180      }
   181
   182      p->name = flb_strdup(name);
   183
   184      if (time_fmt) {
   185          p->time_fmt_full = flb_strdup(time_fmt);
   186          p->time_fmt = flb_strdup(time_fmt);
   187
   188          /* Check if the format is considering the year */
   189          if (strstr(p->time_fmt, "%Y") || strstr(p->time_fmt, "%y")) {
   190              p->time_with_year = FLB_TRUE;
   191          }
   192          else if (strstr(p->time_fmt, "%s")) {
   193              is_epoch = FLB_TRUE;
   194              p->time_with_year = FLB_TRUE;
   195          }
   196          else {
   197              size = strlen(p->time_fmt);
   198              p->time_with_year = FLB_FALSE;
   199              p->time_fmt_year = flb_malloc(size + 4);
   200              if (!p->time_fmt_year) {
   201                  flb_errno();
   202                  flb_parser_destroy(p);
   203                  return NULL;
   204              }
   205
   206              /* Append the year at the beginning */
   207              tmp = p->time_fmt_year;
   208              *tmp++ = '%';
   209              *tmp++ = 'Y';
   210              *tmp++ = ' ';
   211
   212              memcpy(tmp, p->time_fmt, size);
   213              tmp += size;
   214              *tmp++ = '\0';
   215          }
   216
   217          /* Check if the format contains a timezone (%z) */
   218          if (strstr(p->time_fmt, "%z") || strstr(p->time_fmt, "%Z") ||
   219              strstr(p->time_fmt, "%SZ") || strstr(p->time_fmt, "%S.%LZ")) {
   220  #if defined(FLB_HAVE_GMTOFF) || !defined(FLB_HAVE_SYSTEM_STRPTIME)
   221              p->time_with_tz = FLB_TRUE;
   222  #else
   223              flb_error("[parser] timezone offset not supported");
   224              flb_error("[parser] you cannot use %%z/%%Z on this platform");
   225              flb_free(p);
   226              return NULL;
   227  #endif
   228          }
   229
   230          /*
   231           * Check if the format expect fractional seconds
   232           *
   233           * Since strptime(3) does not support fractional seconds, this
   234           * requires a workaround/hack in our parser. This is a known
   235           * issue and addressed in different ways in other languages.
   236           *
   237           * The following links are a good reference:
   238           *
   239           * - http://stackoverflow.com/questions/7114690/how-to-parse-syslog-timestamp
   240           * - http://code.activestate.com/lists/python-list/521885/
   241           */
   242          if (is_epoch == FLB_TRUE) {
   243              tmp = strstr(p->time_fmt, "%s.%L");
   244          }
   245          else if (p->time_with_year == FLB_TRUE) {
   246              tmp = strstr(p->time_fmt, "%S.%L");
   247          }
   248          else {
   249              tmp = strstr(p->time_fmt_year, "%s.%L");
   250
   251              if (tmp == NULL) {
   252                  tmp = strstr(p->time_fmt_year, "%S.%L");
   253              }
   254          }
   255          if (tmp) {
   256              tmp[2] = '\0';
   257              p->time_frac_secs = (tmp + 5);
   258          }
   259          else {
   260              /* same as above but with comma seperator */
   261              if (p->time_with_year == FLB_TRUE) {
   262                  tmp = strstr(p->time_fmt, "%S,%L");
   263              }
   264              else {
   265                  tmp = strstr(p->time_fmt_year, "%s,%L");
   266
   267                  if (tmp == NULL) {
   268                      tmp = strstr(p->time_fmt_year, "%S,%L");
   269                  }
   270              }
   271              if (tmp) {
   272                  tmp[2] = '\0';
   273                  p->time_frac_secs = (tmp + 5);
   274              }
   275              else {
   276                  p->time_frac_secs = NULL;
   277              }
   278          }
   279
   280          /* Optional fixed timezone offset */
   281          if (time_offset) {
   282              diff = 0;
   283              len = strlen(time_offset);
   284              ret = flb_parser_tzone_offset(time_offset, len, &diff);
   285              if (ret == -1) {
   286                  flb_free(p);
   287                  return NULL;
   288              }
   289              p->time_offset = diff;
   290          }
   291      }
   292
   293      if (time_key) {
   294          p->time_key = flb_strdup(time_key);
   295      }
   296
   297      p->time_keep = time_keep;
   298      p->types = types;
   299      p->types_len = types_len;
